"use strict";
const fs=require('fs'),assert=require('assert');
const path='Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json';
const raw=fs.readFileSync(path,'utf8');
const root=JSON.parse(raw);
const keys=new Map();
function visit(v) {
  if (Array.isArray(v)) {for(const item of v)visit(item);return;}
  if (v===null||typeof v!=='object')return;
  for(const [k,val] of Object.entries(v)){
    keys.set(k,(keys.get(k)||0)+1);
    visit(val);
  }
}
visit(root);
const letters="abcdefghijklmnopqrstuvwxyz";
const allocated=new Map(),inverse=new Map(),firstUsed=new Set();
for(const [key,count] of keys){
 const initial=key[0];
 assert(letters.includes(initial),'Non-lowercase initial: '+key);
 let alias;
 if(!firstUsed.has(initial)){
   alias=initial;firstUsed.add(initial);
 }else{
   for(const suffix of letters){
     const candidate=initial+suffix;
     if(!inverse.has(candidate)){alias=candidate;break;}
   }
 }
 assert(alias,'No 2-character alias available for '+key);
 assert(!inverse.has(alias));
 assert(alias[0]===initial);
 assert(alias.length===1||alias.length===2);
 allocated.set(key,alias);
 inverse.set(alias,key);
}
function transform(v){
 if(Array.isArray(v))return v.map(transform);
 if(v===null||typeof v!=='object')return v;
 const out={};
 for(const [k,val] of Object.entries(v))out[allocated.get(k)]=transform(val);
 return out;
}
function reverse(v){
 if(Array.isArray(v))return v.map(reverse);
 if(v===null||typeof v!=='object')return v;
 const out={};
 for(const [k,val] of Object.entries(v))out[inverse.get(k)]=reverse(val);
 return out;
}
const compact=transform(root);
assert.deepStrictEqual(reverse(compact),root);
const pairs=[...keys].map(([key,occurrences])=>({alias:allocated.get(key),key,occurrences})).sort((a,b)=>a.alias.localeCompare(b.alias,'en'));
const compactText=JSON.stringify(compact);
console.log("MAPPING_DATA_BEGIN");
console.log(JSON.stringify({source_path:path,original_characters:raw.length,original_minified_characters:JSON.stringify(root).length,alias_minified_characters:compactText.length,unique_keys:keys.size,one_character_alias_count:pairs.filter(p=>p.alias.length===1).length,two_character_alias_count:pairs.filter(p=>p.alias.length===2).length,all_keys_first_letter_preserved:true,roundtrip_validated:true,aliases:pairs},null,2));
console.log("MAPPING_DATA_END");
NODE
